import{_ as t,a0 as l,w as o,s as c,ao as d,I as p,x as a,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"命令列快速技巧：如何定位一個文件 | LCTT x X-CMD","titleTemplate":false,"description":"命令列快速技巧：如何定位一個文件 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令列快速技巧：如何定位一個文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令列快速技巧：如何定位一個文件 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20181105 Commandline quick tips- How to locate a file","title":"命令列快速技巧：如何定位一個文件","tag":"201811","desc":""},"relativePath":"201811/20181105 Commandline quick tips- How to locate a file.md","filePath":"[post].md"}'),r={name:"201811/20181105 Commandline quick tips- How to locate a file.md"};function h(g,s,k,u,b,m){const n=l("Link");return o(),c("div",null,[s[15]||(s[15]=d(`<h1 id="命令列快速技巧-如何定位一個文件" tabindex="-1">命令列快速技巧：如何定位一個文件 <a class="header-anchor" href="#命令列快速技巧-如何定位一個文件" aria-label="Permalink to “命令列快速技巧：如何定位一個文件”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/10/commandlinequicktips-816x345.jpg" alt=""></p><p>我們都會有文件存儲在電腦裏 —— 目錄、相片、源代碼等等。它們是如此之多。也無疑超出了我的記憶範圍。要是毫無目標，找到正確的那一個可能會很費時間。在這篇文章裏我們來看一下如何在命令列裏找到需要的文件，特別是快速找到你想要的那一個。</p><p>好消息是 Linux 命令列專門設計了很多非常有用的命令列工具在你的電腦上查找文件。下面我們看一下它們其中三個：<code>ls</code>、<code>tree</code> 和 <code>find</code>。</p><h3 id="ls" tabindex="-1">ls <a class="header-anchor" href="#ls" aria-label="Permalink to “ls”">​</a></h3><p>如果你知道文件在哪裏，你只需要列出它們或者查看有關它們的信息，<code>ls</code> 就是為此而生的。</p><p>只需運行 <code>ls</code> 就可以列出當下目錄中所有可見的文件和目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>Documents Music Pictures Videos notes.txt</span></span></code></pre></div><p>添加 <code>-l</code> 選項可以查看文件的相關信息。同時再加上 <code>-h</code> 選項，就可以用一種人們易讀的格式查看文件的大小：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -lh</span></span>
<span class="line"><span>total 60K</span></span>
<span class="line"><span>drwxr-xr-x 2 adam adam 4.0K Nov 2 13:07 Documents</span></span>
<span class="line"><span>drwxr-xr-x 2 adam adam 4.0K Nov 2 13:07 Music</span></span>
<span class="line"><span>drwxr-xr-x 2 adam adam 4.0K Nov 2 13:13 Pictures</span></span>
<span class="line"><span>drwxr-xr-x 2 adam adam 4.0K Nov 2 13:07 Videos</span></span>
<span class="line"><span>-rw-r--r-- 1 adam adam 43K Nov 2 13:12 notes.txt</span></span></code></pre></div><p><code>ls</code> 也可以搜索一個指定位置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls Pictures/</span></span>
<span class="line"><span>trees.png wallpaper.png</span></span></code></pre></div><p>或者一個指定文件 —— 即便只跟着名字的一部分：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls *.txt</span></span>
<span class="line"><span>notes.txt</span></span></code></pre></div><p>少了點什麼？想要查看一個隱藏文件？沒問題，使用 <code>-a</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -a</span></span>
<span class="line"><span>. .bash_logout .bashrc Documents Pictures notes.txt</span></span>
<span class="line"><span>.. .bash_profile .vimrc Music Videos</span></span></code></pre></div><p><code>ls</code> 還有很多其他有用的選項，你可以把它們組合在一起獲得你想要的效果。可以使用以下命令瞭解更多：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man ls</span></span></code></pre></div><h3 id="tree" tabindex="-1">tree <a class="header-anchor" href="#tree" aria-label="Permalink to “tree”">​</a></h3><p>如果你想查看你的文件的樹狀結構，<code>tree</code> 是一個不錯的選擇。可能你的系統上沒有默認安裝它，你可以使用包管理 DNF 手動安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install tree</span></span></code></pre></div><p>如果不帶任何選項或者參數地運行 <code>tree</code>，將會以當前目錄開始，顯示出包含其下所有目錄和文件的一個樹狀圖。提醒一下，這個輸出可能會非常大，因為它包含了這個目錄下的所有目錄和文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tree</span></span>
<span class="line"><span>.</span></span>
<span class="line"><span>|-- Documents</span></span>
<span class="line"><span>| |-- notes.txt</span></span>
<span class="line"><span>| |-- secret</span></span>
<span class="line"><span>| | \`-- christmas-presents.txt</span></span>
<span class="line"><span>| \`-- work</span></span>
<span class="line"><span>| |-- project-abc</span></span>
<span class="line"><span>| | |-- README.md</span></span>
<span class="line"><span>| | |-- do-things.sh</span></span>
<span class="line"><span>| | \`-- project-notes.txt</span></span>
<span class="line"><span>| \`-- status-reports.txt</span></span>
<span class="line"><span>|-- Music</span></span>
<span class="line"><span>|-- Pictures</span></span>
<span class="line"><span>| |-- trees.png</span></span>
<span class="line"><span>| \`-- wallpaper.png</span></span>
<span class="line"><span>|-- Videos</span></span>
<span class="line"><span>\`-- notes.txt</span></span></code></pre></div><p>如果列出的太多了，使用 <code>-L</code> 選項，並在其後加上你想查看的層級數，可以限制列出文件的層級：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tree -L 2</span></span>
<span class="line"><span>.</span></span>
<span class="line"><span>|-- Documents</span></span>
<span class="line"><span>| |-- notes.txt</span></span>
<span class="line"><span>| |-- secret</span></span>
<span class="line"><span>| \`-- work</span></span>
<span class="line"><span>|-- Music</span></span>
<span class="line"><span>|-- Pictures</span></span>
<span class="line"><span>| |-- trees.png</span></span>
<span class="line"><span>| \`-- wallpaper.png</span></span>
<span class="line"><span>|-- Videos</span></span>
<span class="line"><span>\`-- notes.txt</span></span></code></pre></div><p>你也可以顯示一個指定目錄的樹狀圖：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tree Documents/work/</span></span>
<span class="line"><span>Documents/work/</span></span>
<span class="line"><span>|-- project-abc</span></span>
<span class="line"><span>| |-- README.md</span></span>
<span class="line"><span>| |-- do-things.sh</span></span>
<span class="line"><span>| \`-- project-notes.txt</span></span>
<span class="line"><span>\`-- status-reports.txt</span></span></code></pre></div><p>如果使用 <code>tree</code> 列出的是一個很大的樹狀圖，你可以把它跟 <code>less</code> 組合使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tree | less</span></span></code></pre></div><p>再一次，<code>tree</code> 有很多其他的選項可以使用，你可以把他們組合在一起發揮更強大的作用。man 手冊頁有所有這些選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man tree</span></span></code></pre></div><h3 id="find" tabindex="-1">find <a class="header-anchor" href="#find" aria-label="Permalink to “find”">​</a></h3><p>那麼如果不知道文件在哪裏呢？就讓我們來找到它們吧！</p><p>要是你的系統中沒有 <code>find</code>，你可以使用 DNF 安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install findutils</span></span></code></pre></div><p>運行 <code>find</code> 時如果沒有添加任何選項或者參數，它將會遞歸列出當前目錄下的所有文件和目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find</span></span>
<span class="line"><span>.</span></span>
<span class="line"><span>./Documents</span></span>
<span class="line"><span>./Documents/secret</span></span>
<span class="line"><span>./Documents/secret/christmas-presents.txt</span></span>
<span class="line"><span>./Documents/notes.txt</span></span>
<span class="line"><span>./Documents/work</span></span>
<span class="line"><span>./Documents/work/status-reports.txt</span></span>
<span class="line"><span>./Documents/work/project-abc</span></span>
<span class="line"><span>./Documents/work/project-abc/README.md</span></span>
<span class="line"><span>./Documents/work/project-abc/do-things.sh</span></span>
<span class="line"><span>./Documents/work/project-abc/project-notes.txt</span></span>
<span class="line"><span>./.bash_logout</span></span>
<span class="line"><span>./.bashrc</span></span>
<span class="line"><span>./Videos</span></span>
<span class="line"><span>./.bash_profile</span></span>
<span class="line"><span>./.vimrc</span></span>
<span class="line"><span>./Pictures</span></span>
<span class="line"><span>./Pictures/trees.png</span></span>
<span class="line"><span>./Pictures/wallpaper.png</span></span>
<span class="line"><span>./notes.txt</span></span>
<span class="line"><span>./Music</span></span></code></pre></div><p>但是 <code>find</code> 真正強大的是你可以使用文件名進行搜索：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find -name do-things.sh</span></span>
<span class="line"><span>./Documents/work/project-abc/do-things.sh</span></span></code></pre></div><p>或者僅僅是名字的一部分 —— 像是文件後綴。我們來找一下所有的 .txt 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find -name &quot;*.txt&quot;</span></span>
<span class="line"><span>./Documents/secret/christmas-presents.txt</span></span>
<span class="line"><span>./Documents/notes.txt</span></span>
<span class="line"><span>./Documents/work/status-reports.txt</span></span>
<span class="line"><span>./Documents/work/project-abc/project-notes.txt</span></span>
<span class="line"><span>./notes.txt</span></span></code></pre></div><p>你也可以根據大小尋找文件。如果你的空間不足的時候，這種方法也許特別有用。現在來列出所有大於 1 MB 的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find -size +1M</span></span>
<span class="line"><span>./Pictures/trees.png</span></span>
<span class="line"><span>./Pictures/wallpaper.png</span></span></code></pre></div><p>當然也可以搜索一個具體的目錄。假如我想在我的 Documents 文件夾下找一個文件，而且我知道它的名字裏有 “project” 這個詞：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find Documents -name &quot;*project*&quot;</span></span>
<span class="line"><span>Documents/work/project-abc</span></span>
<span class="line"><span>Documents/work/project-abc/project-notes.txt</span></span></code></pre></div><p>除了文件它還顯示目錄。你可以限制僅搜索查詢文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find Documents -name &quot;*project*&quot; -type f</span></span>
<span class="line"><span>Documents/work/project-abc/project-notes.txt</span></span></code></pre></div><p>最後再一次，<code>find</code> 還有很多供你使用的選項，要是你想使用它們，man 手冊頁絕對可以幫到你：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man find</span></span></code></pre></div><hr>`,50)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://fedoramagazine.org/commandline-quick-tips-locate-file/"},{default:i(()=>[...s[0]||(s[0]=[a("https://fedoramagazine.org/commandline-quick-tips-locate-file/",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://fedoramagazine.org/author/asamalik/"},{default:i(()=>[...s[2]||(s[2]=[a("Adam Šamalík",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(n,{href:"https://github.com/dianbanjiu"},{default:i(()=>[...s[4]||(s[4]=[a("dianbanjiu",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const C=t(r,[["render",h]]);export{y as __pageData,C as default};
